  (() => {
    // 1. Obtener payload entrante del Webhook
    const wh = $('Webhook').item.json.body || {};
    const whData = Array.isArray(wh.data) ? wh.data[0] : (wh.data || {});
    const key = whData.key || {};

    // 2. Extraer JID dinámico del usuario entrante
    let jid = key.remoteJid || whData.remoteJid || wh.sender || ($('Edit Fields').item.json.body && $('Edit Fields').item.json.body.phone) || '';
    const altJid = key.remoteJidAlt || '';


    const KNOWN_LID_MAP = {
      '241362709702330@lid': '584142554590@s.whatsapp.net',
      '241362709702330': '584142554590@s.whatsapp.net',
      '188364414275735@lid': '584142650088@s.whatsapp.net',
      '188364414275735': '584142650088@s.whatsapp.net',
      '10256516157671@lid': '584241389058@s.whatsapp.net',
      '10256516157671': '584241389058@s.whatsapp.net',
      '96662381996845@lid': '584123001155@s.whatsapp.net',
      '230602116187442@lid': '584141241044@s.whatsapp.net',
      '178436621353702@lid': '584145920871@s.whatsapp.net',
      '215061509184567@lid': '584241329949@s.whatsapp.net',
      '164700037067258@lid': '584125832703@s.whatsapp.net'
    };

    if (KNOWN_LID_MAP[jid]) { jid = KNOWN_LID_MAP[jid]; } else if (jid.endsWith('@lid')) {
      if (altJid && !altJid.endsWith('@lid')) {
        jid = altJid;
      } else if (whData.participant && !whData.participant.endsWith('@lid')) {
        jid = whData.participant;
      }
    }

    // 3. Sanitizar a dígitos puros E.164
    let cleanNum = jid.replace(/@.*/, '').replace(/\D/g, '');

    // 4. Normalizar formato nacional venezolano (04XX -> 584XX)
    if (cleanNum.startsWith('04') && cleanNum.length === 11) {
      cleanNum = '58' + cleanNum.slice(1);
    }

    // 5.0. GUARDARRAÍL MILITAR DE LISTA NEGRA: Prohibición absoluta de despacho hacia 00584166251587
    const BLACKLISTED_RECIPIENTS = ['4166251587', '584166251587', '04166251587', '00584166251587'];
    if (BLACKLISTED_RECIPIENTS.some(b => cleanNum.endsWith(b) || cleanNum === b)) {
      throw new Error("ACCESO DENEGADO [LISTA NEGRA]: El número " + cleanNum + " está bloqueado permanentemente y tiene prohibido recibir o enviar cualquier mensaje.");
    }

    // 5. GUARDARRAÍL: La única línea bot es +58 424 153 3712 (evitar bucle)
    const OFFICIAL_BOT_NUMBERS = ['584241533712', '04241533712'];
    if (!cleanNum || OFFICIAL_BOT_NUMBERS.includes(cleanNum) || cleanNum.length < 10) {
      if ($json.carrier_phone && !OFFICIAL_BOT_NUMBERS.includes($json.carrier_phone.replace(/\D/g, '')) && $json.carrier_phone.replace(/\D/g, '').length >= 10) {
        cleanNum = $json.carrier_phone.replace(/\D/g, '');
        if (cleanNum.startsWith('04') && cleanNum.length === 11) cleanNum = '58' + cleanNum.slice(1);
      } else if (wh.data && wh.data.key && wh.data.key.remoteJid && !OFFICIAL_BOT_NUMBERS.includes(wh.data.key.remoteJid.replace(/\D/g, ''))) {
        cleanNum = wh.data.key.remoteJid.replace(/@.*/, '').replace(/\D/g, '');
        if (cleanNum.startsWith('04') && cleanNum.length === 11) cleanNum = '58' + cleanNum.slice(1);
      }
    }

    // 6. Sanitizar texto: convertir \n literales a saltos de línea reales y viñetas • a '- '
    let sendText = ($json.final_text || $json.output || 'Estimado abonado, su consulta fue recibida.');
    sendText = String(sendText).replace(/\\n/g, '\n').replace(/•\s*/g, '- ');

    // 7. Retornar payload estricto para Evolution API con linkPreview: false
    return JSON.stringify({
      "number": cleanNum,
      "text": sendText,
      "linkPreview": false,
      "options": {
        "delay": ($json.human_delay_ms || 1200),
        "presence": "composing",
        "linkPreview": false
      }
    });
  })()
}}

