    const charCount = cleanText.length;
    let baseDelay = 800;
    if (charCount > 250) {
        baseDelay = 1800;
    } else if (charCount > 100) {
        baseDelay = 1400;
    } else if (charCount > 50) {
        baseDelay = 1100;
    }
    const jitter = Math.floor(Math.random() * 300) - 120;
    const dynamicDelay = Math.min(Math.max(baseDelay + jitter, 650), 2200);
